  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 21, $j$6.1 Revelation: John on Patmos and the Seven Churches$j$, $j${"readings": [{"title": "Revelation 1 (King James Version)", "url": "/portal/bible/Revelation/1"}, {"title": "Revelation 2 (King James Version)", "url": "/portal/bible/Revelation/2"}, {"title": "Revelation 3 (King James Version)", "url": "/portal/bible/Revelation/3"}], "body": "Read Revelation 1, Revelation 2 and Revelation 3 in the King James Version. Then read this lesson.\n\nRevelation is the last book of the Bible. It was written by the apostle John near the end of the first century, when he was an old man and was on the island of Patmos because of his witness for Jesus. The book begins with a vision of the risen Christ, who says that He is the first and the last, that He is alive for evermore, and that He holds the keys of hell and of death. Jesus then sent seven letters to seven churches in Asia Minor. He praised what was good, corrected what was wrong, and called each church to repent and to overcome. To the church at Ephesus He said, Thou hast left thy first love. To Smyrna He said, Be thou faithful unto death, and I will give thee a crown of life. To Laodicea He said, Behold, I stand at the door, and knock.\n\nKey words: revelation, Patmos, first love, faithful, overcome.\n\nYour task: (1) Tell who wrote Revelation and where he was. (2) Write Revelation 1:18 in your own words. (3) Choose one of the seven churches and tell what Jesus said to it.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Welcome to Unit 6, our last unit. The book of Revelation is the final book of the Bible. Many people think it is only about frightening events, but the first verse tells us what the book is really about. Revelation 1:1 says, The Revelation of Jesus Christ, which God gave unto him, to shew unto his servants things which must shortly come to pass; and he sent and signified it by his angel unto his servant John: This is a revelation of Jesus Christ. It shows us who He is and how the story ends. Verse 3 adds a blessing. Blessed is he that readeth, and they that hear the words of this prophecy, and keep those things which are written therein: for the time is at hand.\n\nThe writer is John, the same apostle who wrote the Gospel and the three letters. He was now an old man. Revelation 1:9 says, I John, who also am your brother, and companion in tribulation, and in the kingdom and patience of Jesus Christ, was in the isle that is called Patmos, for the word of God, and for the testimony of Jesus Christ. Patmos is a small rocky island in the Aegean Sea, where John had been sent because he would not stop preaching about Jesus.\n\nOn that island John saw a vision of the risen Lord. He was so overcome that he fell at His feet. Revelation 1:17 and 18 says, And when I saw him, I fell at his feet as dead. And he laid his right hand upon me, saying unto me, Fear not; I am the first and the last: I am he that liveth, and was dead; and, behold, I am alive for evermore, Amen; and have the keys of hell and of death. Jesus is alive, and He holds the keys. Earlier in verse 8 He said, I am Alpha and Omega, the beginning and the ending, saith the Lord, which is, and which was, and which is to come, the Almighty. Alpha and Omega are the first and last letters of the Greek alphabet. Jesus is the beginning and the end.\n\nIn chapters 2 and 3 Jesus sent seven short letters to seven churches in Asia Minor. These were real churches, and each letter speaks to their real condition. To Ephesus, a hard working church, He said in Revelation 2:4, Nevertheless I have somewhat against thee, because thou hast left thy first love. Hard work cannot replace love for Jesus. To Smyrna, a suffering church, He said in Revelation 2:10, be thou faithful unto death, and I will give thee a crown of life. To Laodicea, a comfortable church, He said in Revelation 3:16, So then because thou art lukewarm, and neither cold nor hot, I will spue thee out of my mouth. Yet He spoke with love. Revelation 3:19 says, As many as I love, I rebuke and chasten: be zealous therefore, and repent. Then came one of the most tender invitations in the Bible. Revelation 3:20 says, Behold, I stand at the door, and knock: if any man hear my voice, and open the door, I will come in to him, and will sup with him, and he with me. Jesus does not force the door open. He knocks, and He waits for us to open.\n\nEach letter ends with a promise to the one who overcomes. Revelation 3:21 says, To him that overcometh will I grant to sit with me in my throne, even as I also overcame, and am set down with my Father in his throne.\n\nYour task is to tell who wrote Revelation and where he was, write Revelation 1:18 in your own words, and choose one of the seven churches and tell what Jesus said to it. Then take the four question check.\n\nJesus is alive, He holds the keys, and He is knocking at the door. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.1 Revelation: John on Patmos and the Seven Churches$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 22, $j$6.2 The Throne in Heaven and the Lamb Who Was Slain$j$, $j${"readings": [{"title": "Revelation 4 (King James Version)", "url": "/portal/bible/Revelation/4"}, {"title": "Revelation 5 (King James Version)", "url": "/portal/bible/Revelation/5"}, {"title": "Revelation 7 (King James Version)", "url": "/portal/bible/Revelation/7"}], "body": "Read Revelation 4, Revelation 5 and Revelation 7 in the King James Version. Then read this lesson.\n\nIn chapters 4 and 5 John was taken in the Spirit to the throne room of heaven. He saw God on His throne surrounded by worship. The living creatures cried, Holy, holy, holy, LORD God Almighty, and the elders worshiped Him because He created all things. In God's hand was a scroll sealed with seven seals, and no one was found worthy to open it. Then John was told that the Lion of the tribe of Juda had prevailed, but when he looked he saw a Lamb as it had been slain. The Lamb is Jesus, who died for sinners. All heaven sang that the Lamb is worthy to receive power, riches, wisdom, strength, honour, glory and blessing. In chapter 7 John saw a great multitude from every nation standing before the throne.\n\nKey words: throne, worthy, Lamb, redeemed, multitude.\n\nYour task: (1) Tell what John saw in heaven in Revelation 4. (2) Write Revelation 5:12 in your own words. (3) Explain why Jesus is called both the Lion and the Lamb.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "In the last lesson we saw the risen Christ and His seven letters to the churches. Now John is invited into heaven. Revelation 4 describes the throne room of God. John saw a throne with One sitting on it, a rainbow around the throne, and living creatures and elders around it. The whole room was filled with worship.\n\nRevelation 4:8 says, And the four beasts had each of them six wings about him; and they were full of eyes within: and they rest not day and night, saying, Holy, holy, holy, LORD God Almighty, which was, and is, and is to come. Then the elders fell down before God and said in verse 11, Thou art worthy, O Lord, to receive glory and honour and power: for thou hast created all things, and for thy pleasure they are and were created. In heaven, everything centers on the worship of God. Our worship on earth is a small picture of that.\n\nIn chapter 5 John saw a scroll in God's right hand, sealed with seven seals. An angel asked who was worthy to open it, and no one could. John wept. Then one of the elders spoke to him. Revelation 5:5 says, And one of the elders saith unto me, Weep not: behold, the Lion of the tribe of Juda, the Root of David, hath prevailed to open the book, and to loose the seven seals thereof. John expected to see a lion. But look at what he saw next. Verse 6 says, And I beheld, and, lo, in the midst of the throne and of the four beasts, and in the midst of the elders, stood a Lamb as it had been slain. Jesus is the Lion of Judah because He is a king and a conqueror. He is the Lamb because He won the victory by giving His life for us.\n\nHeaven then broke into a new song. Revelation 5:9 says, And they sung a new song, saying, Thou art worthy to take the book, and to open the seals thereof: for thou wast slain, and hast redeemed us to God by thy blood out of every kindred, and tongue, and people, and nation; The redeemed come from every nation. And verse 12 says, Saying with a loud voice, Worthy is the Lamb that was slain to receive power, and riches, and wisdom, and strength, and honour, and glory, and blessing. Verse 13 shows that all creation joins in. Blessing, and honour, and glory, and power, be unto him that sitteth upon the throne, and unto the Lamb for ever and ever.\n\nIn chapter 7 John saw a picture of God's people. Revelation 7:9 says, After this I beheld, and, lo, a great multitude, which no man could number, of all nations, and kindreds, and people, and tongues, stood before the throne, and before the Lamb, clothed with white robes, and palms in their hands; And they cried, as verse 10 says, Salvation to our God which sitteth upon the throne, and unto the Lamb. In the middle of the troubles of this world, the book of Revelation lets us see the throne. God is still reigning.\n\nYour task is to tell what John saw in heaven in Revelation 4, write Revelation 5:12 in your own words, and explain why Jesus is called both the Lion and the Lamb. Then take the four question check.\n\nThe Lamb is worthy, and heaven is full of worship. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.2 The Throne in Heaven and the Lamb Who Was Slain$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 23, $j$6.3 The Victory of Christ: Faithful and True$j$, $j${"readings": [{"title": "Revelation 12 (King James Version)", "url": "/portal/bible/Revelation/12"}, {"title": "Revelation 19 (King James Version)", "url": "/portal/bible/Revelation/19"}, {"title": "Revelation 20 (King James Version)", "url": "/portal/bible/Revelation/20"}], "body": "Read Revelation 12, Revelation 19 and Revelation 20 in the King James Version. Then read this lesson.\n\nThe middle chapters of Revelation describe a great struggle between good and evil, using symbols that the first readers understood. The message of these chapters is that Jesus wins. In Revelation 12:11 John wrote that believers overcame by the blood of the Lamb, by the word of their testimony, and because they loved not their lives unto the death. In chapter 19 John saw heaven opened and Christ riding a white horse. He is called Faithful and True, His name is The Word of God, and He has written on Him the name KING OF KINGS, AND LORD OF LORDS. In chapter 20 John saw the great white throne, where the dead are judged and the book of life is opened. Christians have studied the details of these chapters in different ways, but all agree that Christ will return in victory and that every person will stand before God.\n\nKey words: overcame, testimony, Faithful and True, King of kings, judgment.\n\nYour task: (1) Tell how Revelation 12:11 says believers overcame. (2) Write Revelation 19:16 in your own words. (3) Explain what John saw at the great white throne in Revelation 20.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Today we look at the chapters of Revelation that show the final victory of Christ. This part of the book uses vivid symbols, such as beasts, dragons and horsemen. Christians through the centuries have studied these symbols and sometimes explained them in different ways. As students, we will focus on what is clear and what all believers agree on: Jesus wins, and every person will stand before God.\n\nThe book of Revelation was written to encourage believers who were suffering. Many of them were being persecuted by the Roman Empire. John wanted them to know how this struggle will end. In chapter 12 he showed how God's people can overcome. Revelation 12:11 says, And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death. Believers overcome by the blood of Jesus, by their testimony, and by their willingness to stay faithful, even in hard times.\n\nChapter 19 gives us a picture of the return of Christ. Revelation 19:11 says, And I saw heaven opened, and behold a white horse; and he that sat upon him was called Faithful and True, and in righteousness he doth judge and make war. The name Faithful and True tells us that Jesus always keeps His word. Verse 12 says, His eyes were as a flame of fire, and on his head were many crowns; and he had a name written, that no man knew, but he himself. Verse 13 says, And he was clothed with a vesture dipped in blood: and his name is called The Word of God. This links us back to the Gospel of John, which began by calling Jesus the Word. Verse 16 gives His title. And he hath on his vesture and on his thigh a name written, KING OF KINGS, AND LORD OF LORDS. No ruler, empire or power is greater than Jesus.\n\nChapter 20 describes a solemn moment. Revelation 20:11 says, And I saw a great white throne, and him that sat on it, from whose face the earth and the heaven fled away; and there was found no place for them. Verse 12 says, And I saw the dead, small and great, stand before God; and the books were opened: and another book was opened, which is the book of life: and the dead were judged out of those things which were written in the books, according to their works. Everyone, great and small, will stand before God. Verse 15 says, And whosoever was not found written in the book of life was cast into the lake of fire. This is a serious truth, and it is the reason the gospel must be shared. Those who trust in Jesus have their names written in the book of life.\n\nYour task is to tell how Revelation 12:11 says believers overcame, write Revelation 19:16 in your own words, and explain what John saw at the great white throne. Then take the four question check.\n\nJesus is Faithful and True, and He is King of kings. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.3 The Victory of Christ: Faithful and True$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 24, $j$6.4 The New Heaven and the New Earth$j$, $j${"readings": [{"title": "Revelation 21 (King James Version)", "url": "/portal/bible/Revelation/21"}, {"title": "Revelation 22 (King James Version)", "url": "/portal/bible/Revelation/22"}], "body": "Read Revelation 21 and Revelation 22 in the King James Version. Then read this lesson.\n\nThe Bible ends with a promise of hope. In Revelation 21 John saw a new heaven and a new earth, and the holy city, new Jerusalem, coming down from God out of heaven. God will dwell with His people, and He will wipe away all tears from their eyes. There will be no more death, sorrow, crying or pain, because the former things are passed away. The One on the throne said, Behold, I make all things new. In chapter 22 John saw the river of the water of life and the tree of life, and Jesus said, I am Alpha and Omega, the beginning and the end. The book closes with an invitation: whosoever will, let him take the water of life freely. The last prayer is, Even so, come, Lord Jesus. The final words are, The grace of our Lord Jesus Christ be with you all. Amen.\n\nKey words: new heaven, tears, make all things new, water of life, invitation.\n\nYour task: (1) Tell what Revelation 21:4 promises. (2) Write Revelation 21:5 in your own words. (3) Explain the invitation in Revelation 22:17.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "This is the last lesson of our New Testament survey, and it is about the last two chapters of the Bible. After all of the struggle and judgment in Revelation, the story ends with joy. God's plan from the beginning was to live with His people, and the last chapters show that plan complete.\n\nRevelation 21:1 says, And I saw a new heaven and a new earth: for the first heaven and the first earth were passed away; and there was no more sea. Verse 2 says, And I John saw the holy city, new Jerusalem, coming down from God out of heaven, prepared as a bride adorned for her husband. Then comes the great promise in verse 3. And I heard a great voice out of heaven saying, Behold, the tabernacle of God is with men, and he will dwell with them, and they shall be his people, and God himself shall be with them, and be their God. In the Garden of Eden, God walked with Adam and Eve. In the new creation, God lives with His people forever.\n\nRevelation 21:4 may be the most comforting verse in the Bible for people who are hurting. And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away. If you have lost a loved one, if you are sick or if you are afraid, this promise is for you. Then the One on the throne spoke. Revelation 21:5 says, And he that sat upon the throne said, Behold, I make all things new. And he said unto me, Write: for these words are true and faithful. God does not just fix the old world. He makes all things new.\n\nVerse 6 says, And he said unto me, It is done. I am Alpha and Omega, the beginning and the end. I will give unto him that is athirst of the fountain of the water of life freely. And verse 7 says, He that overcometh shall inherit all things; and I will be his God, and he shall be my son.\n\nIn chapter 22 John saw the river and the tree of life, as in the Garden of Eden. Revelation 22:1 says, And he shewed me a pure river of water of life, clear as crystal, proceeding out of the throne of God and of the Lamb. Verse 2 says, In the midst of the street of it, and on either side of the river, was there the tree of life, which bare twelve manner of fruits, and yielded her fruit every month: and the leaves of the tree were for the healing of the nations. Verse 13 repeats the words of Jesus. I am Alpha and Omega, the beginning and the end, the first and the last.\n\nThe Bible ends with an invitation to everyone. Revelation 22:17 says, And the Spirit and the bride say, Come. And let him that heareth say, Come. And let him that is athirst come. And whosoever will, let him take the water of life freely. The offer is free, and it is for whosoever will. The last prayer of the Bible is found in verse 20. He which testifieth these things saith, Surely I come quickly. Amen. Even so, come, Lord Jesus. And the Bible closes with a blessing in verse 21. The grace of our Lord Jesus Christ be with you all. Amen.\n\nYour task is to tell what Revelation 21:4 promises, write Revelation 21:5 in your own words, and explain the invitation in Revelation 22:17. Then take the four question check and the Unit 6 quiz. After that, you are ready for the final assessment and the final exam.\n\nYou have studied the whole New Testament, from the birth of Jesus to the new heaven and new earth. Excellence, Faith, Purpose. May the grace of our Lord Jesus Christ be with you."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.4 The New Heaven and the New Earth$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 6, $j$Assessment 6: Hope in the Book of Revelation$j$, $j${"prompt": "Choose one passage from this unit: Revelation 1:18, Revelation 3:20, Revelation 5:12, Revelation 12:11, Revelation 19:16, Revelation 21:4 or Revelation 22:17. Write one paragraph of 150 to 200 words. Quote the passage from the King James Version with the reference, explain what it meant to the first readers who were suffering, and tell how it gives hope to a student today.", "rubric": "Total 100. Accurate quotation of the passage with the reference: 20. Explains the meaning for the first readers: 30. Shows how the passage gives hope today: 30. Clear writing and correct conventions: 20."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 6: Hope in the Book of Revelation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 6, $j$Discussion 6: Living in Light of Christ's Return$j$, $j${"prompt": "Revelation teaches that Jesus is alive, that He reigns, and that He will return in victory. How should this change the way a student lives each day? Name one habit or choice you will make because you believe that Jesus is coming again. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 6: Living in Light of Christ's Return$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 26, $j$Check 6.1: Revelation: John on Patmos and the Seven Churches$j$, $j${"questions": [{"q": "According to Revelation 1:1, what is the book of Revelation?", "options": ["A list of kings", "The Revelation of Jesus Christ", "A history of Rome", "A book of laws"]}, {"q": "Where was John when he received the vision?", "options": ["In Rome", "In Jerusalem", "In the isle called Patmos", "In Galilee"]}, {"q": "What did Jesus say to the church at Ephesus in Revelation 2:4?", "options": ["You are a faithful church", "You have left your first love", "You have no works", "You are rich"]}, {"q": "What does Jesus say in Revelation 3:20?", "options": ["Build a wall", "I will leave you", "Wait for the end", "I stand at the door, and knock"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Revelation: John on Patmos and the Seven Churches$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,1,3}'::int[], array[$j$Revelation 1:1 calls the book The Revelation of Jesus Christ.$j$,$j$John was on the isle called Patmos for the word of God and the testimony of Jesus Christ.$j$,$j$Jesus said, Thou hast left thy first love.$j$,$j$Jesus stands at the door and knocks, and He comes in to anyone who opens.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Revelation: John on Patmos and the Seven Churches$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 27, $j$Check 6.2: The Throne in Heaven and the Lamb Who Was Slain$j$, $j${"questions": [{"q": "What did the four living creatures say day and night in Revelation 4:8?", "options": ["Holy, holy, holy, LORD God Almighty", "The end is near", "Glory to the king of Rome", "Peace on earth"]}, {"q": "Why do the elders say God is worthy in Revelation 4:11?", "options": ["Because He rules Rome", "Because He keeps the law", "Because He has created all things", "Because He is the strongest of kings"]}, {"q": "What did John see standing in the midst of the throne in Revelation 5:6?", "options": ["A great eagle", "A mighty king", "A Lamb as it had been slain", "An angel with a sword"]}, {"q": "What did the great multitude from every nation cry in Revelation 7:10?", "options": ["Revenge on the earth", "Judgment to the wicked", "Peace to the world", "Salvation to our God which sitteth upon the throne, and unto the Lamb"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: The Throne in Heaven and the Lamb Who Was Slain$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,2,3}'::int[], array[$j$They cried, Holy, holy, holy, LORD God Almighty, which was, and is, and is to come.$j$,$j$God is worthy because He created all things.$j$,$j$John saw a Lamb as it had been slain, which is Jesus.$j$,$j$They cried, Salvation to our God which sitteth upon the throne, and unto the Lamb.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: The Throne in Heaven and the Lamb Who Was Slain$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 28, $j$Check 6.3: The Victory of Christ: Faithful and True$j$, $j${"questions": [{"q": "According to Revelation 12:11, how did believers overcome?", "options": ["By the blood of the Lamb and by the word of their testimony", "By building walls", "By escaping to the desert", "By the strength of armies"]}, {"q": "What is the rider on the white horse called in Revelation 19:11?", "options": ["Son of David", "Faithful and True", "Prince of Rome", "Judge of Israel"]}, {"q": "What name is written on the vesture of Christ in Revelation 19:16?", "options": ["KING OF KINGS, AND LORD OF LORDS", "Teacher of the law", "Lamb of the temple", "Prophet of Galilee"]}, {"q": "According to Revelation 20:15, whose names are found in the book of life?", "options": ["Only kings", "Only the old", "Those who trust in Jesus have their names written there", "Only the rich"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: The Victory of Christ: Faithful and True$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,0,2}'::int[], array[$j$They overcame by the blood of the Lamb, by the word of their testimony, and by loving not their lives unto death.$j$,$j$The rider is called Faithful and True.$j$,$j$His name is KING OF KINGS, AND LORD OF LORDS.$j$,$j$Those whose names are written in the book of life are saved through Jesus.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: The Victory of Christ: Faithful and True$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 29, $j$Check 6.4: The New Heaven and the New Earth$j$, $j${"questions": [{"q": "What does Revelation 21:4 say God will wipe away?", "options": ["All tears from their eyes", "Every kingdom", "The old books", "Every temple"]}, {"q": "What does the One on the throne say in Revelation 21:5?", "options": ["Keep the old law", "I make all things new", "I will return tomorrow", "Build a house"]}, {"q": "What did John see flowing out of the throne of God in Revelation 22:1?", "options": ["A sea of glass", "A golden road", "A fire", "A pure river of water of life"]}, {"q": "According to Revelation 22:17, who may take the water of life freely?", "options": ["Only priests", "Only the first believers", "Only the wealthy", "Whosoever will"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: The New Heaven and the New Earth$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,3,3}'::int[], array[$j$God shall wipe away all tears from their eyes, and there shall be no more death, sorrow, crying or pain.$j$,$j$He said, Behold, I make all things new.$j$,$j$John saw a pure river of water of life, clear as crystal.$j$,$j$Whosoever will, let him take the water of life freely.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: The New Heaven and the New Earth$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 30, $j$Unit Quiz 6: The Book of Revelation$j$, $j${"questions": [{"q": "Who wrote the book of Revelation, and where was he when he received the vision?", "options": ["Paul, in a Roman prison", "James, in Antioch", "Peter, in Jerusalem", "John, on the isle of Patmos"]}, {"q": "What did Jesus say to Smyrna in Revelation 2:10?", "options": ["You are neither cold nor hot", "You have left your first love", "Be thou faithful unto death, and I will give thee a crown of life", "Leave the city"]}, {"q": "Who did John see in the midst of the throne in Revelation 5:6?", "options": ["A great eagle", "A mighty king", "An angel", "A Lamb as it had been slain"]}, {"q": "What name is written on Christ in Revelation 19:16?", "options": ["KING OF KINGS, AND LORD OF LORDS", "Prince of Peace", "High Priest of the temple", "Teacher of Israel"]}, {"q": "What does Revelation 21:4 promise?", "options": ["No more death, sorrow, crying or pain", "A new temple", "An earthly kingdom for a thousand years", "The return of the law"]}, {"q": "What is the final invitation in Revelation 22:17?", "options": ["Build a city", "Give an offering", "Wait until the end", "Whosoever will, let him take the water of life freely"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: The Book of Revelation$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,3,0,0,3}'::int[], array[$j$John received the vision on the isle called Patmos.$j$,$j$Jesus encouraged the suffering church to stay faithful, with the promise of a crown of life.$j$,$j$The Lamb is Jesus, who died for us and is worthy to open the book.$j$,$j$His name is KING OF KINGS, AND LORD OF LORDS.$j$,$j$God will wipe away all tears, and the former things are passed away.$j$,$j$The Bible ends with a free invitation to anyone who is thirsty.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: The Book of Revelation$j$ on conflict (item_id) do nothing;
